"use client"

import * as React from "react"
import { Dialog as DialogPrimitive } from "@base-ui/react/dialog"
import { cn } from "@/lib/utils"

import { Button } from "@/components/ui/button"
import { IconButton } from "@/components/ui/icon-button"
import { XIcon } from "lucide-react"

function Dialog({ ...props }: DialogPrimitive.Root.Props) {
  return <DialogPrimitive.Root data-slot="dialog" {...props} />
}

function DialogTrigger({ ...props }: DialogPrimitive.Trigger.Props) {
  return <DialogPrimitive.Trigger data-slot="dialog-trigger" {...props} />
}

function DialogPortal({ ...props }: DialogPrimitive.Portal.Props) {
  return <DialogPrimitive.Portal data-slot="dialog-portal" {...props} />
}

function DialogClose({ ...props }: DialogPrimitive.Close.Props) {
  return <DialogPrimitive.Close data-slot="dialog-close" {...props} />
}

function DialogOverlay({
  className,
  ...props
}: DialogPrimitive.Backdrop.Props) {
  return (
    <DialogPrimitive.Backdrop
      data-slot="dialog-overlay"
      className={cn(
        "fixed inset-0 isolate z-50 bg-black/10 supports-backdrop-filter:backdrop-blur-xs data-open:animate-in data-open:fade-in-0 data-open:duration-base data-closed:animate-out data-closed:fade-out-0 data-closed:duration-fast",
        className
      )}
      {...props}
    />
  )
}

const DIALOG_SIZES = {
  sm: "",
  md: "sm:max-w-[512px]",
  lg: "sm:max-w-[720px]",
} as const

const DIALOG_FOOTER_LAYOUTS = {
  inline: "flex-row justify-end",
  stacked: "flex-col-reverse *:w-full",
} as const

const SURFACE_WIDTHS = {
  sm: "max-w-sm",
  md: "max-w-[512px]",
  lg: "max-w-[720px]",
} as const

function DialogCloseButton({
  onClick,
}: {
  onClick?: React.MouseEventHandler<HTMLElement>
}) {
  return (
    <DialogPrimitive.Close
      data-slot="dialog-close"
      onClick={onClick}
      render={
        <IconButton
          variant="plain"
          className="absolute top-2 right-2 border-transparent shadow-none"
          size="sm"
        />
      }
    >
      <XIcon
      />
      <span className="sr-only">Close</span>
    </DialogPrimitive.Close>
  )
}

function DialogContent({
  className,
  children,
  showCloseButton = true,
  overlayClassName,
  size = "sm",
  appearance = "surface",
  showOverlay = true,
  placement = "center",
  ...props
}: DialogPrimitive.Popup.Props & {
  showCloseButton?: boolean
  /** Restyle the backdrop, e.g. a flat page colour for a screen that is only the modal. */
  overlayClassName?: string
  /** Figma Dialog / Surface Size: Small 384, Medium 512, Large 720. */
  size?: "sm" | "md" | "lg"
  /** Figma look (default) or the earlier plain look. */
  appearance?: "surface" | "plain"
  /** Non-modal dialog: omit the backdrop. */
  showOverlay?: boolean
  /** Figma dialog placement: center or bottom-right (help panels). */
  placement?: "center" | "bottom-right"
}) {
  return (
    <DialogPortal>
      {showOverlay && <DialogOverlay className={overlayClassName} />}
      <DialogPrimitive.Popup
        data-slot="dialog-content"
        data-size={size}
        data-appearance={appearance}
        data-placement={placement}
        className={cn(
          "fixed top-1/2 left-1/2 z-50 grid w-full grid-cols-[minmax(0,1fr)] [--surface:var(--popover)] max-w-[calc(100%-2rem)] -translate-x-1/2 -translate-y-1/2 gap-4 rounded-xl bg-popover p-4 text-sm text-popover-foreground ring-1 ring-foreground/10 outline-none sm:max-w-sm data-open:animate-in data-open:fade-in-0 data-open:zoom-in-92 data-open:slide-in-from-bottom-2 data-open:duration-slow data-open:ease-overshoot data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-96 data-closed:duration-fast data-closed:ease-exit",
          "group/dialog",
          DIALOG_SIZES[size],
          appearance === "surface" && "shadow-xl",
          placement === "bottom-right" && "right-4 bottom-4 top-auto left-auto translate-x-0 translate-y-0",
          className
        )}
        {...props}
      >
        {children}
        {showCloseButton && <DialogCloseButton />}
      </DialogPrimitive.Popup>
    </DialogPortal>
  )
}

function DialogHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="dialog-header"
      className={cn("flex flex-col gap-2 group-data-[appearance=surface]/dialog:pr-9", className)}
      {...props}
    />
  )
}

const DIALOG_ICON_VARIANTS = {
  default: "bg-muted text-foreground",
  warning: "bg-tint-yellow text-tint-text-yellow",
  destructive: "bg-tint-red text-tint-text-red",
} as const

// A colored icon circle for confirm/warning/destructive dialogs, matching
// the icon-header pattern used across most design-system modal libraries
// (e.g. "Delete project?" with a red trash icon above the title).
function DialogIcon({
  variant = "default",
  className,
  ...props
}: React.ComponentProps<"div"> & { variant?: keyof typeof DIALOG_ICON_VARIANTS }) {
  return (
    <div
      data-slot="dialog-icon"
      className={cn(
        "mb-1 flex size-10 items-center justify-center rounded-full [&_svg]:size-5",
        DIALOG_ICON_VARIANTS[variant],
        className
      )}
      {...props}
    />
  )
}

function DialogFooter({
  className,
  showCloseButton = false,
  children,
  band,
  layout,
  start,
  ...props
}: React.ComponentProps<"div"> & {
  showCloseButton?: boolean
  /** Figma "Band": `true` paints the footer fill; omitted = band inside surface dialogs. */
  band?: boolean
  /** Figma Footer Layout: `inline` one row, `stacked` one column with the primary on top. */
  layout?: "inline" | "stacked"
  /** Figma Footer Layout "Split": action at the left edge (Back, Compare). */
  start?: React.ReactNode
}) {
  return (
    <div
      data-slot="dialog-footer"
      data-layout={layout}
      data-band={band === true ? "" : undefined}
      className={cn(
        layout === undefined
          ? "-mx-4 -mb-4 flex flex-col-reverse gap-2 rounded-b-xl p-4 sm:flex-row sm:justify-end"
          : ["-mx-4 -mb-4 flex gap-2 rounded-b-xl p-4", DIALOG_FOOTER_LAYOUTS[layout]],
        band === true ? "bg-bg-page" : band === undefined ? "group-data-[appearance=surface]/dialog:bg-bg-page" : "",
        className
      )}
      {...props}
    >
      {start && (
        <div data-slot="dialog-footer-start" className="flex items-center sm:mr-auto">
          {start}
        </div>
      )}
      {children}
      {showCloseButton && (
        <DialogPrimitive.Close render={<Button variant="plain" />}>
          Close
        </DialogPrimitive.Close>
      )}
    </div>
  )
}

function DialogTitle({ className, ...props }: DialogPrimitive.Title.Props) {
  return (
    <DialogPrimitive.Title
      data-slot="dialog-title"
      className={cn(
        "font-heading text-base leading-none font-medium group-data-[appearance=surface]/dialog:leading-6 group-data-[appearance=surface]/dialog:font-semibold",
        className
      )}
      {...props}
    />
  )
}

function DialogDescription({
  className,
  ...props
}: DialogPrimitive.Description.Props) {
  return (
    <DialogPrimitive.Description
      data-slot="dialog-description"
      className={cn(
        "text-sm text-muted-foreground *:[a]:underline *:[a]:underline-offset-3 *:[a]:hover:text-foreground",
        className
      )}
      {...props}
    />
  )
}

function DialogBody({
  className,
  scrollable = false,
  tabIndex,
  role,
  ...props
}: React.ComponentProps<"div"> & {
  /** Figma Scrollable body: title and footer stay fixed, the body scrolls. With aria-label or aria-labelledby the scrolling body is announced as a region. */
  scrollable?: boolean
}) {
  return (
    <div
      data-slot="dialog-body"
      data-scrollable={scrollable ? "" : undefined}
      tabIndex={scrollable ? (tabIndex ?? 0) : tabIndex}
      role={role ?? (scrollable && (props["aria-label"] || props["aria-labelledby"]) ? "region" : undefined)}
      className={cn(
        "flex min-w-0 flex-col gap-4",
        scrollable && "-mx-4 max-h-[296px] overflow-y-auto border-y border-border px-4 py-3 has-[+[data-slot=dialog-footer]]:-mb-4 focus-ring",
        className
      )}
      {...props}
    />
  )
}

function DialogProgress({
  step,
  steps,
  label,
  className,
  ...props
}: Omit<React.ComponentProps<"div">, "children"> & {
  step: number
  steps: number
  label?: React.ReactNode
}) {
  const total = Math.max(1, Math.floor(steps))
  const current = Math.min(Math.max(1, Math.floor(step)), total)
  return (
    <div
      data-slot="dialog-progress"
      role="progressbar"
      aria-valuemin={1}
      aria-valuemax={total}
      aria-valuenow={current}
      aria-valuetext={`Step ${current} of ${total}`}
      aria-label={`Step ${current} of ${total}`}
      className={cn("flex flex-col gap-2", className)}
      {...props}
    >
      <div className="flex items-center justify-between text-xs">
        <span className="text-text-secondary">Step {current} of {total}</span>
        {label && <span className="font-medium text-foreground">{label}</span>}
      </div>
      <div className="flex gap-1">
        {Array.from({ length: total }, (_, index) => (
          <span
            key={index}
            aria-hidden
            data-state={index < current ? "done" : "todo"}
            className={cn("h-1 flex-1 rounded-full", index < current ? "bg-primary" : "bg-border")}
          />
        ))}
      </div>
    </div>
  )
}

function DialogSurface({
  size = "sm",
  appearance = "surface",
  showCloseButton = true,
  onClose,
  className,
  children,
  ...props
}: React.ComponentProps<"div"> & {
  /** Figma Dialog / Surface Size: Small 384, Medium 512, Large 720. */
  size?: "sm" | "md" | "lg"
  /** Figma look (default) or the earlier plain look. */
  appearance?: "surface" | "plain"
  showCloseButton?: boolean
  /** Called when the corner close button is pressed (the static panel has no open state of its own). */
  onClose?: () => void
}) {
  return (
    <DialogPrimitive.Root open={false}>
      <div
        role="group"
        data-slot="dialog-surface"
        data-size={size}
        data-appearance={appearance}
        className={cn(
          "group/dialog relative grid w-full grid-cols-[minmax(0,1fr)] [--surface:var(--popover)] gap-4 rounded-xl bg-popover p-4 text-left text-sm text-popover-foreground ring-1 ring-foreground/10",
          SURFACE_WIDTHS[size],
          appearance === "surface" && "shadow-xl",
          className
        )}
        {...props}
      >
        {children}
        {showCloseButton && <DialogCloseButton onClick={onClose} />}
      </div>
    </DialogPrimitive.Root>
  )
}

export {
  Dialog,
  DialogBody,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogIcon,
  DialogOverlay,
  DialogPortal,
  DialogProgress,
  DialogSurface,
  DialogTitle,
  DialogTrigger,
}

import * as React from "react"
import { Button as ButtonPrimitive } from "@base-ui/react/button"
import { cva, type VariantProps } from "class-variance-authority"
import { Check, Loader2, RotateCw } from "lucide-react"
import { cn } from "@/lib/utils"

// Same states as Button (see button.tsx and the Figma Button / Icon set): the filled variants use fixed
// hover and pressed fills (brand-700/800, red-800/900, dark-400/500, bg-page/bg-subtle on neutral surfaces)
// instead of brightness-95, and focus is the shared 2 px focus-ring (owner rule 31 Oct 2026). The gradient top
// stop is 85 % primary + 15 % brand-500 (4.73:1 with a white icon); hover and pressed step the gradient to
// brand-600/700 and brand-700/800. The light variant's icon is light-1000 (5.93:1 on light-600); it has no
// Figma counterpart, hover and pressed step to the lighter light-500 and light-400 so the icon keeps >= 3:1.
const iconButtonVariants = cva(
  "group/icon-button inline-flex shrink-0 items-center justify-center border border-transparent transition duration-fast ease-entrance outline-none select-none shadow-[0px_1px_1px_0px_rgba(16,24,40,0.05)] active:scale-[0.97] motion-reduce:active:scale-100 disabled:pointer-events-none disabled:opacity-40 [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        plain: "bg-card border-border-control text-foreground hover:bg-bg-page data-expanded:bg-bg-subtle data-expanded:hover:bg-bg-subtle active:bg-bg-subtle focus-ring",
        primary:
          "border-primary bg-primary text-primary-foreground hover:border-(color:--brand-700) hover:bg-(--brand-700) active:border-(color:--brand-800) active:bg-(--brand-800) focus-ring",
        brand:
          "border-brand-primary bg-brand-primary text-brand-primary-foreground hover:border-(color:--brand-700) hover:bg-(--brand-700) active:border-(color:--brand-800) active:bg-(--brand-800) focus-ring",
        gradient:
          "border-primary bg-gradient-to-b from-[color-mix(in_srgb,var(--primary)_85%,var(--brand-500))] to-primary text-primary-foreground shadow-[0px_1px_1px_0px_rgba(16,24,40,0.05),inset_0px_1px_2px_0px_rgba(255,255,255,0.35)] hover:from-(--brand-600) hover:to-(--brand-700) active:from-(--brand-700) active:to-(--brand-800) focus-ring",
        dark: "bg-inverse text-text-inverse hover:bg-(--dark-400) hover:text-white active:bg-(--dark-500) active:text-white focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-offset-0 focus-visible:outline-(color:--dark-300)",
        light: "bg-(--light-600) text-(--light-1000) hover:bg-(--light-500) data-expanded:bg-bg-subtle data-expanded:hover:bg-bg-subtle active:bg-(--light-400) focus-ring",
        outline: "bg-card border-primary text-foreground hover:border-tint-text-indigo hover:bg-tint-indigo hover:text-tint-text-indigo data-expanded:bg-bg-subtle data-expanded:hover:bg-bg-subtle active:bg-bg-subtle focus-ring",
        // Figma Type=ghost / destructive (added Sep 2026)
        ghost: "bg-transparent text-foreground shadow-none hover:bg-bg-page data-expanded:bg-bg-subtle data-expanded:hover:bg-bg-subtle active:bg-bg-subtle focus-ring",
        destructive:
          "border-destructive bg-destructive text-destructive-foreground hover:border-red-800 hover:bg-red-800 active:border-red-900 active:bg-red-900 focus-ring-error",
      },
      shape: {
        rounded: "rounded-md",
        circle: "rounded-full",
      },
      size: {
        sm: "size-8 [&_svg]:size-4",
        md: "size-9 [&_svg]:size-[18px]",
        lg: "size-10 [&_svg]:size-5",
        xl: "size-11 [&_svg]:size-[22px]",
        "2xl": "size-12 [&_svg]:size-6",
      },
    },
    defaultVariants: {
      variant: "primary",
      shape: "rounded",
      size: "md",
    },
  }
)

type IconButtonPhase = "idle" | "pending" | "success" | "error"

function IconButton({
  className,
  variant,
  shape,
  size,
  children,
  onClick,
  pending,
  phase,
  expanded,
  ...props
}: ButtonPrimitive.Props &
  VariantProps<typeof iconButtonVariants> & {
    /**
     * Shows a spinner in place of the icon, in the same square, and ignores presses.
     * The button stays focusable and keeps its colour (it is not disabled).
     */
    pending?: boolean
    /**
     * Async feedback in the same square: pending shows a spinner, success a check, error a retry icon.
     * The size never changes. The accessible name is yours: change the aria-label with the phase
     * (for example Copy link, Copying, Copied, Retry copying).
     */
    phase?: IconButtonPhase
    /**
     * Marks a trigger whose menu or panel is open: sets aria-expanded and the pressed surface
     * (bg-bg-subtle) on the quiet variants. Leave it undefined when the button does not control a popup.
     */
    expanded?: boolean
  }) {
  const status: IconButtonPhase = phase ?? (pending ? "pending" : "idle")
  const isIdle = status === "idle"

  const resolvedVariant = variant ?? "primary"
  const effectiveVariant =
    status === "error" && ["primary", "brand", "gradient"].includes(resolvedVariant)
      ? "destructive"
      : variant

  const quiet = ["plain", "ghost", "outline"].includes(resolvedVariant)

  let statusIcon: React.ReactNode = null
  if (status === "pending") {
    statusIcon = (
      <Loader2 aria-hidden className="animate-spin motion-reduce:animate-none" />
    )
  } else if (status === "success") {
    statusIcon = (
      <Check aria-hidden strokeWidth={1.5} className={quiet ? "text-text-success" : undefined} />
    )
  } else if (status === "error") {
    statusIcon = (
      <RotateCw aria-hidden strokeWidth={1.5} className={quiet ? "text-text-error" : undefined} />
    )
  }

  const handleClick: NonNullable<ButtonPrimitive.Props["onClick"]> = (event) => {
    if (status === "pending") {
      event.preventDefault()
      return
    }
    onClick?.(event)
  }

  return (
    <ButtonPrimitive
      data-slot="icon-button"
      className={cn(iconButtonVariants({ variant: isIdle ? variant : effectiveVariant, shape, size, className }))}
      aria-expanded={expanded}
      data-expanded={expanded ? "" : undefined}
      data-phase={isIdle ? undefined : status}
      aria-busy={isIdle ? undefined : status === "pending" ? true : undefined}
      data-pending={isIdle ? undefined : status === "pending" ? "" : undefined}
      onClick={isIdle ? onClick : handleClick}
      {...props}
    >
      {isIdle ? children : statusIcon}
    </ButtonPrimitive>
  )
}

export { IconButton, iconButtonVariants }
export type { IconButtonPhase }

import type { CnFunction } from "cn"
import { createCn } from "cn/config"

/**
 * clsx + tailwind-merge, taught WunderUI's own theme utilities so they merge
 * in the right group: `text-label-sm` is a font size (not a text colour, which
 * dropped it next to `text-text-tertiary`), `bg-gradient-*` a background image
 * (not a colour that `bg-card` would remove), and the motion utilities
 * `ease-entrance …` and `duration-fast …` replace each other.
 */
export const cn: CnFunction = createCn({
  extend: {
    classGroups: {
      "font-size": [{ text: ["label-sm", "micro"] }],
      "bg-image": [
        {
          bg: [
            "gradient-primary",
            "gradient-indigo",
            "gradient-blue",
            "gradient-purple",
            "gradient-pink",
            "gradient-red",
            "gradient-orange",
            "gradient-yellow",
            "gradient-green",
            "gradient-alternative",
            "gradient-slate",
            "gradient-dark",
          ],
        },
      ],
      ease: [{ ease: ["entrance", "exit", "move", "overshoot", "spring"] }],
      duration: [{ duration: ["instant", "fast", "base", "slow", "deliberate", "ambient"] }],
    },
  },
})

import * as React from "react"
import { Button as ButtonPrimitive } from "@base-ui/react/button"
import { cva, type VariantProps } from "class-variance-authority"
import { Check, Loader2, RotateCw } from "lucide-react"
import { cn } from "@/lib/utils"

// --primary/--brand-primary is the indigo brand color; its text uses
// --primary-foreground/--brand-primary-foreground (white), which is AA-safe
// on indigo. gradient tracks the same primary token (light tint -> primary),
// so its text reuses primary-foreground too. outline keeps a fixed white
// background independent of the primary token, so its text stays a fixed
// dark color (#25272a) rather than tracking primary-foreground, which is
// white and would fail contrast on that fixed white background.
// See /scripts/contrast-audit.mjs.
//
// Hover and pressed on the filled variants are fixed token colours, the Figma values:
// primary and brand go brand-700 on hover and brand-800 pressed (white label 7.0:1 and
// 10.0:1), destructive goes red-800 and red-900 (6.5:1 and 10.6:1), the dark button
// goes dark-400 and dark-500. They replaced brightness-95, which dimmed fill and label
// together and left the pressed state with no colour at all (only a scale). The plain
// button follows the neutral-surface rule: hover bg-page, pressed bg-subtle.
// Focus (owner rule 31 Oct 2026): the border turns indigo and a 2 px indigo-300 outline sits directly on it
// (utility focus-ring); destructive keeps its red hue (focus-ring-error) and the dark button, whose border is
// its fill, gets a dark-300 ring. The gradient hover and pressed states are brand-600/700 and 700/800 stops.
//
// The gradient top stop was #6f74f5, which put the top edge of the button at
// 3.82:1 -- the gradient, not the token, was the failure. #5a5ef4 keeps a
// visible sheen (4.84:1 top, 4.99:1 bottom) and the inset white highlight
// carries the rest of the raised look. Its hover brightened (brightness-105,
// 3.52:1); it now darkens like the other filled variants (4.71:1 top).
const buttonVariants = cva(
  "group/button inline-flex shrink-0 items-center justify-center gap-2 border border-transparent text-sm font-medium whitespace-nowrap transition duration-fast ease-entrance outline-none select-none shadow-[0px_1px_1px_0px_rgba(16,24,40,0.05)] active:not-aria-[haspopup]:scale-[0.97] motion-reduce:active:scale-100 disabled:pointer-events-none disabled:opacity-40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        plain: "bg-card border-border-control text-foreground hover:bg-bg-page data-popup-open:bg-bg-page active:bg-bg-subtle focus-ring",
        primary:
          "border-primary bg-primary text-primary-foreground hover:border-(color:--brand-700) hover:bg-(--brand-700) active:border-(color:--brand-800) active:bg-(--brand-800) focus-ring",
        brand:
          "border-brand-primary bg-brand-primary text-brand-primary-foreground hover:border-(color:--brand-700) hover:bg-(--brand-700) active:border-(color:--brand-800) active:bg-(--brand-800) focus-ring",
        gradient:
          "border-primary bg-gradient-to-b from-[#5a5ef4] to-primary text-primary-foreground shadow-[0px_1px_1px_0px_rgba(16,24,40,0.05),inset_0px_1px_2px_0px_rgba(255,255,255,0.35)] hover:from-(--brand-600) hover:to-(--brand-700) active:from-(--brand-700) active:to-(--brand-800) focus-ring",
        dark: "bg-inverse text-text-inverse hover:bg-(--dark-400) hover:text-white active:bg-(--dark-500) active:text-white focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-offset-0 focus-visible:outline-(color:--dark-300)",
        light: "bg-white bg-clip-padding text-primary hover:bg-(--light-200) focus-ring",
        // Figma Type=blue_outline: indigo rim, link-coloured label, indigo tint on hover.
        outline: "bg-card border-primary text-text-link hover:border-tint-text-indigo hover:bg-tint-indigo hover:text-tint-text-indigo active:bg-bg-subtle active:text-tint-text-indigo focus-ring",
        // Indigo tint: the selected-option look of the button group and segmented selectors.
        tint: "bg-tint-indigo text-tint-text-indigo focus-ring",
        // Figma Type=ghost / destructive / link (added Sep 2026)
        ghost: "bg-transparent text-foreground shadow-none hover:bg-bg-page data-popup-open:bg-bg-page active:bg-bg-subtle focus-ring",
        destructive:
          "border-destructive bg-destructive text-destructive-foreground hover:border-red-800 hover:bg-red-800 active:border-red-900 active:bg-red-900 focus-ring-error",
        link: "bg-transparent px-0! text-text-link shadow-none underline-offset-4 hover:text-text-link-hover hover:underline active:text-text-link-pressed focus-ring",
      },
      shape: {
        rounded: "rounded-md",
        pill: "rounded-full",
      },
      size: {
        // Heights and paddings are density tokens (styles.css): compact 32/36/40/44/48,
        // data-density="comfortable" 36/40/44/48/56. The icon side sits 2 px tighter (2xl 4 px).
        sm: "h-(--control-sm) px-(--control-px-sm) text-sm has-data-[icon=inline-end]:pr-[calc(var(--control-px-sm)-0.125rem)] has-data-[icon=inline-start]:pl-[calc(var(--control-px-sm)-0.125rem)]",
        // Icon sizes follow the Figma Button sets: Small and Regular 16 px, Medium 20 px, Large and Xlarge 24 px. Heights and paddings are unchanged.
        md: "h-(--control-md) px-(--control-px-md) text-sm has-data-[icon=inline-end]:pr-[calc(var(--control-px-md)-0.125rem)] has-data-[icon=inline-start]:pl-[calc(var(--control-px-md)-0.125rem)]",
        lg: "h-(--control-lg) px-(--control-px-lg) text-sm [&_svg:not([class*='size-'])]:size-5 has-data-[icon=inline-end]:pr-[calc(var(--control-px-lg)-0.125rem)] has-data-[icon=inline-start]:pl-[calc(var(--control-px-lg)-0.125rem)]",
        xl: "h-(--control-xl) px-(--control-px-xl) text-base [&_svg:not([class*='size-'])]:size-6 has-data-[icon=inline-end]:pr-[calc(var(--control-px-xl)-0.125rem)] has-data-[icon=inline-start]:pl-[calc(var(--control-px-xl)-0.125rem)]",
        "2xl": "h-(--control-2xl) px-(--control-px-2xl) text-lg [&_svg:not([class*='size-'])]:size-6 has-data-[icon=inline-end]:pr-[calc(var(--control-px-2xl)-0.25rem)] has-data-[icon=inline-start]:pl-[calc(var(--control-px-2xl)-0.25rem)]",
      },
    },
    defaultVariants: {
      variant: "primary",
      shape: "rounded",
      size: "md",
    },
  }
)

type ButtonPhase = "idle" | "pending" | "success" | "error"

function Button({
  className,
  variant,
  shape,
  size,
  children,
  onClick,
  pending,
  phase,
  ...props
}: ButtonPrimitive.Props &
  VariantProps<typeof buttonVariants> & {
    /**
     * Shows a spinner in place of the leading icon and ignores presses.
     * The button stays focusable and keeps its colour (it is not disabled).
     */
    pending?: boolean
    /**
     * Async feedback: pending shows a spinner, success a check, error a retry
     * icon. The label is yours (for example Saving…, Saved, Retry). Keep the
     * width constant with a fixed width on the button so it does not jump
     * between phases.
     */
    phase?: ButtonPhase
  }) {
  const status: ButtonPhase = phase ?? (pending ? "pending" : "idle")
  const isIdle = status === "idle"

  const resolvedVariant = variant ?? "primary"
  const effectiveVariant =
    status === "error" &&
    ["primary", "brand", "gradient"].includes(resolvedVariant)
      ? "destructive"
      : variant

  const filteredChildren = React.Children.toArray(children).filter((child) => {
    if (!React.isValidElement<{ "data-icon"?: string }>(child)) {
      return true
    }
    return child.props["data-icon"] !== "inline-start"
  })

  const quiet = ["plain", "ghost", "outline", "tint"].includes(resolvedVariant)

  let statusIcon: React.ReactNode = null
  if (status === "pending") {
    statusIcon = (
      <Loader2
        aria-hidden
        data-icon="inline-start"
        className="animate-spin motion-reduce:animate-none"
      />
    )
  } else if (status === "success") {
    statusIcon = (
      <Check
        aria-hidden
        data-icon="inline-start"
        strokeWidth={1.5}
        className={quiet ? "text-text-success" : undefined}
      />
    )
  } else if (status === "error") {
    statusIcon = (
      <RotateCw
        aria-hidden
        data-icon="inline-start"
        strokeWidth={1.5}
        className={quiet ? "text-text-error" : undefined}
      />
    )
  }

  const handleClick: NonNullable<ButtonPrimitive.Props["onClick"]> = (event) => {
    if (status === "pending") {
      event.preventDefault()
      return
    }
    onClick?.(event)
  }

  return (
    <ButtonPrimitive
      data-slot="button"
      className={cn(
        buttonVariants({ variant: isIdle ? variant : effectiveVariant, shape, size, className })
      )}
      data-phase={isIdle ? undefined : status}
      aria-busy={isIdle ? undefined : status === "pending" ? true : undefined}
      data-pending={isIdle ? undefined : status === "pending" ? "" : undefined}
      onClick={isIdle ? onClick : handleClick}
      {...props}
    >
      {isIdle ? null : statusIcon}
      {isIdle ? children : filteredChildren}
    </ButtonPrimitive>
  )
}

export { Button, buttonVariants }
export type { ButtonPhase }
